def evaluate_expression(expression):
    # Define the operators and their precedence
    operators = {
        '+': (lambda x, y: x + y, 1),
        '-': (lambda x, y: x - y, 1),
        '*': (lambda x, y: x * y, 2),
        '/': (lambda x, y: x / y, 2),
    }

    # Tokenize the expression into tokens (numbers, operators, and parentheses)
    tokens = []
    token = ''
    in_parentheses = False
    for char in expression:
        if char.isdigit():
            token += char
        elif char == '(':
            in_parentheses = True
        elif char == ')':
            in_parentheses = False
        elif char in operators:
            if in_parentheses:
                tokens.append((char, float(token)))
                token = ''
            else:
                tokens.append((char, None))
        else:
            raise ValueError(f"Invalid character '{char}' in expression")

    if token:
        tokens.append((char, float(token)))

    # Evaluate the expression using operator precedence
    result = None
    while tokens:
        operator, token = tokens.pop(0)
        if token is None:
            left, right = tokens.pop(0), tokens.pop(0)
            result = operators[operator](left, right)
        else:
            result = token

    return result

# Example usage
